-- GATE PACK 0266 triggers (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select c.relname as obj, t.tgname, t.tgenabled::text as enabled, (t.tgtype & 1) = 1 as row_level, (t.tgtype & 2) = 2 as before_trg
from pg_catalog.pg_trigger t join pg_catalog.pg_class c on c.oid = t.tgrelid
where not t.tgisinternal and t.tgname in ('client_legal_name_access_audit_no_update', 'client_legal_name_access_audit_no_truncate')
order by 1, 2;
